function validate([nums, k]) {
  if (nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.some(v => v < 1 || v > 1000)) return 'Each value is between 1 and 1000.';
  if (k < 1 || k > Math.floor(nums.length / 2)) return 'k is between 1 and half the length of nums, rounded down.';
  return null;
}

