function sumOfGoodNumbers(nums, k) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    const beatsLeft = i - k < 0 || nums[i] > nums[i - k];
    const beatsRight = i + k >= nums.length || nums[i] > nums[i + k];
    if (beatsLeft && beatsRight) {
      total += nums[i];
    }
  }
  return total;
}

