function sumOfGoodNumbers(nums, k) {
  // Gather every element exactly k positions away from i, and keep nums[i] only if it beats all of them.
  let sum = 0;
  nums.forEach((value, i) => {
    const partners = [];
    for (let j = 0; j < nums.length; j++) if (Math.abs(i - j) === k) partners.push(nums[j]);
    if (partners.every(partner => value > partner)) sum += value;
  });
  return sum;
}

