function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 2 + Math.floor(rand() * 9);
  // Narrow value ranges create ties, which are never good; wide ones reach the 1000 limit.
  const top = large ? 1000 : [2, 5, 1000][Math.floor(rand() * 3)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const k = 1 + Math.floor(rand() * Math.floor(n / 2));
  return [nums, k];
}
